#include <omp.h>
#include <vector>
#include <cstddef>

double sumOfMinimumElements(std::vector<double> const& x,
                            std::vector<double> const& y) {
    double sum = 0.0;
    std::size_t n = x.size();               // assume x and y have the same length
    #pragma omp parallel for reduction(+:sum) schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        double min_val = (x[i] < y[i]) ? x[i] : y[i];
        sum += min_val;
    }
    return sum;
}
